// ---- the cooked form: point at a cook (docs/SPEC-TABLES.md §7) ----

// PartRowOpen: match the header and POINT. On a match the bytes ARE what this
// build wrote, in this build's layout and this build's byte order, so there
// is nothing to validate and nothing to fix up and the root comes back as it
// lies. On ANY refusal it returns NULL and NAMES the refusal in the caller's
// TableRefuseReason, the first failing clause in §7's order (a wrong build
// version is a re-cook, a foreign order a cross-endian cook, a truncated
// file a bad download, an unaligned base the caller's own buffer), and the
// caller falls back to a wire load, which is the path that carries every
// version. The reason is written on the refusal path only; a caller that
// passes nothing gets the null alone.
//
// It is O(1) IN THE FILE'S SIZE — the header and nothing per node — so a one
// megabyte cook and a one gigabyte cook open in the same time, and a mapped
// file's pages are touched only as they are used. That is a property of
// touching nothing at open rather than a separate mechanism.
//
// PartRow IS FIXED-SIZE, so its cook is ONE REGION OF ONE NODE and not a second
// shape (§7): one struct behind the header, at the region's base, which is
// what this returns. There is no graph below it and nothing to resolve.
//
// There is ONE entry point and no tolerant twin: a build either wrote this
// file or it did not, and the build version is what says which. Validating a
// file whose provenance a person doubts is schema cook-check, offline,
// over the ATTRIBUTION part beside the data — a person's decision, never a
// parameter on a load.
inline const PartRow * PartRowOpen( const void * bytes, uint64_t length, TableRefuseReason * reason = NULL )
{
    return (const PartRow *) TableCookOpen( bytes, length, (uint64_t) sizeof( PartRow ), (uint64_t) alignof( PartRow ), reason );
}

// PartFrameOpen: match the header and POINT. On a match the bytes ARE what this
// build wrote, in this build's layout and this build's byte order, so there
// is nothing to validate and nothing to fix up and the root comes back as it
// lies. On ANY refusal it returns NULL and NAMES the refusal in the caller's
// TableRefuseReason, the first failing clause in §7's order (a wrong build
// version is a re-cook, a foreign order a cross-endian cook, a truncated
// file a bad download, an unaligned base the caller's own buffer), and the
// caller falls back to a wire load, which is the path that carries every
// version. The reason is written on the refusal path only; a caller that
// passes nothing gets the null alone.
//
// It is O(1) IN THE FILE'S SIZE — the header and nothing per node — so a one
// megabyte cook and a one gigabyte cook open in the same time, and a mapped
// file's pages are touched only as they are used. That is a property of
// touching nothing at open rather than a separate mechanism.
//
// PartFrame IS FIXED-SIZE, so its cook is ONE REGION OF ONE NODE and not a second
// shape (§7): one struct behind the header, at the region's base, which is
// what this returns. There is no graph below it and nothing to resolve.
//
// There is ONE entry point and no tolerant twin: a build either wrote this
// file or it did not, and the build version is what says which. Validating a
// file whose provenance a person doubts is schema cook-check, offline,
// over the ATTRIBUTION part beside the data — a person's decision, never a
// parameter on a load.
inline const PartFrame * PartFrameOpen( const void * bytes, uint64_t length, TableRefuseReason * reason = NULL )
{
    return (const PartFrame *) TableCookOpen( bytes, length, (uint64_t) sizeof( PartFrame ), (uint64_t) alignof( PartFrame ), reason );
}

// ---- the cooked form: WRITE a cook (docs/SPEC-TABLES.md §7.6) ----
//
// The bytes are `schema cook`'s, and the tool stays the reference: the two
// writers are held to one file, byte for byte, in both byte orders. A cook is
// content-addressed by (asset hash, build version), so two writers of one
// instance produce ONE artifact or the pair means nothing.

inline void PartRowCookBody( uint8_t * at, const PartRow & value, TableByteOrder order );
inline void PartFrameCookBody( uint8_t * at, const PartFrame & value, TableByteOrder order );

inline void PartRowCookBody( uint8_t * at, const PartRow & value, TableByteOrder order )
{
    ArmorConfigCookBody( at + 0, value.armor, order );
    GunnerSettingsCookBody( at + 40, value.gunner, order );
    table_cook_put( at + 344, (uint64_t) value.part_id, 4, order );
    table_cook_put( at + 348, (uint64_t) value.slot, 1, order );
}

inline void PartFrameCookBody( uint8_t * at, const PartFrame & value, TableByteOrder order )
{
    table_cook_put( at + 0, (uint64_t) value.version, 8, order );
    // all 32 slots: the storage is allocate-max, and a slot past the count rides as it lies (§7.2)
    for ( int32_t i = 0; i < 32; i++ )
    {
        PartRowCookBody( at + 8 + i * 352, value.parts[ i ], order );
    }
    table_cook_put( at + 11272, (uint64_t) (uint32_t) value.parts_count, 4, order );
}

// PartRowCookMeasure: the whole cooked file's bytes — the header, the data part
// and the attribution part (docs/SPEC-TABLES.md §7.1). It answers in int64_t
// because a cook's part lengths are 64 bits: the scale this form exists for is
// a catalog, and a 32-bit answer would reimpose the ceiling §3.1 removed.
//
// PartRow IS FIXED-SIZE, so the answer does not depend on the value: its cook is
// ONE REGION OF ONE NODE (§7) — the record at the region's base, its length
// rounded to the region's alignment, and one directory entry.
inline int64_t PartRowCookMeasure( const PartRow & value )
{
    (void) value;
    return 432; // 64 header + 352 data + 16 attribution
}

// PartRowCook: write one cooked file for the build this code is compiled into,
// in the byte order the caller names. The bytes are `schema cook`'s, byte for
// byte, and the tool is the reference (§7.6).
//
// THE CALLER OWNS THE BUFFER AND NOTHING IS ALLOCATED: measure, then write.
// A capacity short of the measure writes nothing and returns false, which is
// the same contract PartRowMeasure/PartRowSave has on the wire (§6.1).
//
// EVERY BYTE NO FIELD COVERS IS ZERO (§7.2) — interior padding, the record's
// trailing padding, a string's unused tail, the bytes of a union outside its
// set arm, and the slack the rounded data length leaves. It comes from the one
// memset below rather than from a rule per padding site, and it is what makes
// two cooks of one value ONE artifact (§7).
inline bool PartRowCook( const PartRow & value, void * out, uint64_t capacity, TableByteOrder order )
{
    if ( out == NULL ) { return false; }
    const uint64_t need = (uint64_t) PartRowCookMeasure( value );
    if ( capacity < need ) { return false; }
    uint8_t * raw = (uint8_t *) out;
    memset( raw, 0, (size_t) need );
    // the HEADER (§7.1), every word a u64 in the order the file is produced in
    table_cook_put( raw + 0, TableCookMagic, 8, order );
    table_cook_put( raw + 8, BuildVersion, 8, order );
    table_cook_put( raw + 16, (uint64_t) ( order == TableByteOrder::Big ? 2 : 1 ), 8, order );
    table_cook_put( raw + 24, 352, 8, order ); // data_length, rounded to the region's alignment
    table_cook_put( raw + 32, 16, 8, order ); // attribution_length: one entry, one node
    table_cook_put( raw + 40, 8, 8, order ); // the region's alignment
    // the two RESERVED words are zero, and the memset already wrote them
    // the DATA part: the region, which for a fixed root is the record at its base
    PartRowCookBody( raw + 64, value, order );
    // the ATTRIBUTION part: the node directory (§6.3), written beside the data
    // for `schema cook-check` — one entry, the root at offset zero, and its type
    // id is the fnv1a64 of the table's name (§3.1)
    table_cook_put( raw + 416, 0, 8, order );
    table_cook_put( raw + 424, 0x27c461282640b1f0ull, 8, order );
    return true;
}

// PartFrameCookMeasure: the whole cooked file's bytes — the header, the data part
// and the attribution part (docs/SPEC-TABLES.md §7.1). It answers in int64_t
// because a cook's part lengths are 64 bits: the scale this form exists for is
// a catalog, and a 32-bit answer would reimpose the ceiling §3.1 removed.
//
// PartFrame IS FIXED-SIZE, so the answer does not depend on the value: its cook is
// ONE REGION OF ONE NODE (§7) — the record at the region's base, its length
// rounded to the region's alignment, and one directory entry.
inline int64_t PartFrameCookMeasure( const PartFrame & value )
{
    (void) value;
    return 11360; // 64 header + 11280 data + 16 attribution
}

// PartFrameCook: write one cooked file for the build this code is compiled into,
// in the byte order the caller names. The bytes are `schema cook`'s, byte for
// byte, and the tool is the reference (§7.6).
//
// THE CALLER OWNS THE BUFFER AND NOTHING IS ALLOCATED: measure, then write.
// A capacity short of the measure writes nothing and returns false, which is
// the same contract PartFrameMeasure/PartFrameSave has on the wire (§6.1).
//
// EVERY BYTE NO FIELD COVERS IS ZERO (§7.2) — interior padding, the record's
// trailing padding, a string's unused tail, the bytes of a union outside its
// set arm, and the slack the rounded data length leaves. It comes from the one
// memset below rather than from a rule per padding site, and it is what makes
// two cooks of one value ONE artifact (§7).
inline bool PartFrameCook( const PartFrame & value, void * out, uint64_t capacity, TableByteOrder order )
{
    if ( out == NULL ) { return false; }
    const uint64_t need = (uint64_t) PartFrameCookMeasure( value );
    if ( capacity < need ) { return false; }
    uint8_t * raw = (uint8_t *) out;
    memset( raw, 0, (size_t) need );
    // the HEADER (§7.1), every word a u64 in the order the file is produced in
    table_cook_put( raw + 0, TableCookMagic, 8, order );
    table_cook_put( raw + 8, BuildVersion, 8, order );
    table_cook_put( raw + 16, (uint64_t) ( order == TableByteOrder::Big ? 2 : 1 ), 8, order );
    table_cook_put( raw + 24, 11280, 8, order ); // data_length, rounded to the region's alignment
    table_cook_put( raw + 32, 16, 8, order ); // attribution_length: one entry, one node
    table_cook_put( raw + 40, 8, 8, order ); // the region's alignment
    // the two RESERVED words are zero, and the memset already wrote them
    // the DATA part: the region, which for a fixed root is the record at its base
    PartFrameCookBody( raw + 64, value, order );
    // the ATTRIBUTION part: the node directory (§6.3), written beside the data
    // for `schema cook-check` — one entry, the root at offset zero, and its type
    // id is the fnv1a64 of the table's name (§3.1)
    table_cook_put( raw + 11344, 0, 8, order );
    table_cook_put( raw + 11352, 0x7ca1b7fd9e3a2fb1ull, 8, order );
    return true;
}

// ---- relocatability, enforced: the wire is a pure length-prefixed
// stream AND the decoded storage is pointer-free — every closure type
// must stay trivially copyable and standard-layout, so instances can be
// memcpy'd, mmap'd, shared across processes, and walked through
// descriptor offsets. A failure here means a pointer, virtual or
// non-trivial member crept into generated storage.
//
// They ask the COMPILER ITSELF, which is what every C++ standard library
// answers the same two questions with — and it costs this header no
// include at all.
static_assert( __is_trivially_copyable( PartRow ), "PartRow must stay relocatable" );
static_assert( __is_standard_layout( PartRow ), "PartRow must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( PartFrame ), "PartFrame must stay relocatable" );
static_assert( __is_standard_layout( PartFrame ), "PartFrame must stay standard-layout for offsetof" );

// ---- the cook's layout contract (docs/SPEC-TABLES.md §20.3) ----
//
// The compiler derived every number below from the declaration and folded it
// into the BUILD VERSION; these asserts are this compiler saying whether it
// agrees. The model is not self-evidently right — on 32-bit System V
// alignof(uint64_t) is 4, not 8 — which is precisely why it is asserted
// rather than assumed.
static_assert( sizeof( PartRow ) == 352, "PartRow's sizeof moved: the build version was taken over 352, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( PartRow ) == 8, "PartRow's alignof moved: the build version was taken over 8 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PartRow, armor ) == 0, "PartRow's field armor moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PartRow, gunner ) == 40, "PartRow's field gunner moved: the build version was taken over offset 40 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PartRow, part_id ) == 344, "PartRow's field part_id moved: the build version was taken over offset 344 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PartRow, slot ) == 348, "PartRow's field slot moved: the build version was taken over offset 348 (docs/SPEC-TABLES.md §20.3)" );
static_assert( sizeof( PartFrame ) == 11280, "PartFrame's sizeof moved: the build version was taken over 11280, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( PartFrame ) == 8, "PartFrame's alignof moved: the build version was taken over 8 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PartFrame, version ) == 0, "PartFrame's field version moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( PartFrame, parts ) == 8, "PartFrame's field parts moved: the build version was taken over offset 8 (docs/SPEC-TABLES.md §20.3)" );

